      "footnotesUr": "[1] آسمانی کتابوں کے نزول کا مقصد، لوگوں کی ہدایت اور رہنمائی ہے اور یہ مقصد اس وقت حاصل ہو سکتا ہے جب وہ کتاب اس زبان میں ہو جس کو وہ سمجھ سکیں، اس لئے ہر آسمانی کتاب اس قومی زبان میں نازل ہوئی، جس قوم کی ہدایت کے لئے اتاری گئی تھی۔ قرآن کریم کے مخاطب اول چونکہ عرب تھے، اس لئے قرآن بھی عربی زبان میں نازل ہوا۔ علاوہ ازیں عربی زبان اپنی فصاحت و بلاغت اور ادائے معانی کے لحاظ سے دنیا کی بہترین زبان ہے۔ اس لئے اللہ تعالٰی نے اس اشرف الکتاب (قرآن مجید) کو اشرف اللغات (عربی) میں اشرف الرسل (حضرت محمد صلی اللہ علیہ و سلم) پر اشرف الملائکہ (جبرائیل) کے ذریعے سے نازل فرمایا اور مکہ، جہاں اس کا آغاز ہوا، دنیا کا اشرف ترین مقام ہے اور جس مہینے میں نزول کی ابتدا ہوئی وہ بھی اشرف ترین مہینہ، رمضان ہے۔",
