      "number": 6,
      "arFull": "وَكَذٰلِكَ یَجْتَبِیْكَ رَبُّكَ وَیُعَلِّمُكَ مِنْ تَاْوِیْلِ الْاَحَادِیْثِ وَیُتِمُّ نِعْمَتَهٗ عَلَیْكَ وَعَلٰۤی اٰلِ یَعْقُوْبَ كَمَاۤ اَتَمَّهَا عَلٰۤی اَبَوَیْكَ مِنْ قَبْلُ اِبْرٰهِیْمَ وَاِسْحٰقَ ؕ اِنَّ رَبَّكَ عَلِیْمٌ حَكِیْمٌ ۟۠",
      "ur": "اور اسی طرح [1] تجھے تیرا پروردگار برگزیده کرے گا اور تجھے معاملہ فہمی (یا خوابوں کی تعبیر) بھی سکھائے گا اور اپنی نعمت تجھے بھرپور عطا فرمائے گا [2]اور یعقوب کے گھر والوں کو بھی[3]، جیسے کہ اس نے اس سے پہلے تیرے دادا اور پردادا یعنی ابراہیم واسحاق کو بھی بھرپور اپنی نعمت دی، یقیناً تیرا رب بہت بڑے علم واﻻ اور زبردست حکمت واﻻ ہے.",
      "en": "And thus will your Lord choose you and teach you the interpretation of narratives [i.e., events or dreams] and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise.\"",
      "footnotesUr": "[1] یعنی جس طرح تجھے تیرے رب نے نہایت عظمت والا خواب دکھانے کے لئے چن لیا، اسی طرح تیرا رب تجھے برگزیدگی بھی عطا کرے گا اور خوابوں کی تعبیر سکھائے گا۔ تَأْوِيلُ الأَحَادِيثِ کے اصل معنی باتوں کی تہہ تک پہنچنا ہے۔ یہاں خواب کی تعبیر مراد ہے۔\n[2] اس سے مراد نبوت ہے جو یوسف (عليه السلام) کو عطا کی گئی۔ یا وہ انعامات ہیں جن سے مصر میں یوسف (عليه السلام) نوازے گئے۔\n[3] اس سے مراد حضرت یوسف (عليه السلام) کے بھائی، ان کی اولاد وغیرہ ہیں، جو بعد میں انعامات الٰہی کے مستحق بنے۔",
      "footnotesEn": null,
