      "arFull": "قَالُوْا یٰۤاَبَانَا مَا لَكَ لَا تَاْمَنَّا عَلٰی یُوْسُفَ وَاِنَّا لَهٗ لَنٰصِحُوْنَ ۟",
      "ur": "انہوں نے کہا ابا! آخر آپ یوسف (علیہ السلام) کے بارے میں ہم پر اعتبار کیوں نہیں کرتے ہم تو اس کے خیر خواه ہیں.[1]",
      "en": "They said, \"O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?",
