      "number": 21,
      "arFull": "وَقَالَ الَّذِی اشْتَرٰىهُ مِنْ مِّصْرَ لِامْرَاَتِهٖۤ اَكْرِمِیْ مَثْوٰىهُ عَسٰۤی اَنْ یَّنْفَعَنَاۤ اَوْ نَتَّخِذَهٗ وَلَدًا ؕ وَكَذٰلِكَ مَكَّنَّا لِیُوْسُفَ فِی الْاَرْضِ ؗ وَلِنُعَلِّمَهٗ مِنْ تَاْوِیْلِ الْاَحَادِیْثِ ؕ وَاللّٰهُ غَالِبٌ عَلٰۤی اَمْرِهٖ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا یَعْلَمُوْنَ ۟",
      "ur": "مصر والوں میں سے جس نے اسے خریدا تھا اس نے اپنی بیوی [1] سے کہا کہ اسے بہت عزت واحترام کے ساتھ رکھو، بہت ممکن ہے کہ یہ ہمیں فائده پہنچائے یا اسے ہم اپنا بیٹا ہی بنا لیں، یوں ہم نے مصر کی سرزمین میں یوسف کا قدم جما [2]دیا کہ ہم اسے خواب کی تعبیر کا کچھ علم سکھا دیں۔ اللہ اپنے ارادے پر غالب ہے لیکن اکثر لوگ بے علم ہوتے ہیں.",
      "en": "And the one from Egypt[590] who bought him said to his wife, \"Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son.\" And thus, We established Joseph in the land that We might teach him the interpretation of events [i.e., dreams]. And Allāh is predominant over His affair, but most of the people do not know.",
      "footnotesUr": "[1] کہا جاتا ہے کہ مصر پر اس وقت ریان بن ولید حکمران تھا اور یہ عزیز مصر، جس نے یوسف (عليه السلام) کو خریدا اس کا وزیر خزانہ تھا، اس کی بیوی کا نام بعض نے راعیل اور بعض نے زلیخا بتلایا ہے واللہ اعلم۔\n[2] یعنی جس طرح ہم نے یوسف (عليه السلام) کو کنویں سے ظالم بھائیوں سے نجات دی، اسی طرح ہم نے یوسف (عليه السلام) کو سرزمین مصر میں ایک معقول اچھا ٹھکانا عطا کیا۔",
      "footnotesEn": "[590] The minister in charge of supplies, whose title was al-ʿAzeez.",
