      "number": 25,
      "arFull": "وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِیْصَهٗ مِنْ دُبُرٍ وَّاَلْفَیَا سَیِّدَهَا لَدَا الْبَابِ ؕ قَالَتْ مَا جَزَآءُ مَنْ اَرَادَ بِاَهْلِكَ سُوْٓءًا اِلَّاۤ اَنْ یُّسْجَنَ اَوْ عَذَابٌ اَلِیْمٌ ۟",
      "ur": "دونوں دروازے کی طرف دوڑے[1] اور اس عورت نے یوسف کا کرتا پیچھے کی طرف سے کھینچ کر پھاڑ ڈاﻻ اور دروازے کے پاس ہی عورت کا شوہر دونوں کو مل گیا، تو کہنے لگی جو شخص تیری بیوی کے ساتھ برا اراده کرے بس اس کی سزا یہی ہے کہ اسے قید کر دیا جائے یا اور کوئی دردناک سزا دی جائے.[2]",
      "en": "And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, \"What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?\"",
      "footnotesUr": "[1] جب حضرت یوسف (عليه السلام) نے دیکھا کہ وہ عورت برائی کے ارتکاب پر مصر ہے، تو وہ باہر نکلنے کے لئے دروازے کی طرف دوڑے، یوسف (عليه السلام) کے پیچھے انہیں پکڑنے کے لئے عورت بھی دوڑی۔ یوں دونوں دروازے کی طرف لپکے اور دوڑے۔\n[2] یعنی خاوند کو دیکھتے ہی خود معصوم بن گئی اور مجرم تمام تر یوسف (عليه السلام) کو قرار دے کر ان کے لئے سزا بھی تجویز کر دی۔ حالانکہ صورت حال اس کے برعکس تھی، مجرم خود تھی جب کہ حضرت یوسف (عليه السلام) بالکل بےگناہ اور برائی سے بچنے کے خواہش مند اور اس کے لئے کوشاں تھے۔",
