      "arFull": "فَلَمَّا رَاٰ قَمِیْصَهٗ قُدَّ مِنْ دُبُرٍ قَالَ اِنَّهٗ مِنْ كَیْدِكُنَّ ؕ اِنَّ كَیْدَكُنَّ عَظِیْمٌ ۟",
