      "arFull": "وَقَالَ الَّذِیْ نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ اُمَّةٍ اَنَا اُنَبِّئُكُمْ بِتَاْوِیْلِهٖ فَاَرْسِلُوْنِ ۟",
