      "arFull": "ثُمَّ یَاْتِیْ مِنْ بَعْدِ ذٰلِكَ عَامٌ فِیْهِ یُغَاثُ النَّاسُ وَفِیْهِ یَعْصِرُوْنَ ۟۠",
      "ur": "اس کے بعد جو سال آئے گا اس میں لوگوں پر خوب بارش برسائی جائے گی اور اس میں (شیرہٴ انگور بھی) خوب نچوڑیں گے.[1]",
      "en": "Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes].\"",
      "footnotesUr": "[1] یعنی قحط کے سال گزرنے کے بعد پھر خوب بارش ہوگی، جس کے نتیجے میں کثرت پیداوار ہوگی اور تم انگوروں سے شیرہ نچوڑو گے، زیتوں سے تیل نکالو گے اور جانوروں سے دودھ دوہو گے۔ خواب کی اس تعبیر کو خواب سے کیسی لطیف مناسبت حاصل ہے، جسے صرف وہی شخص سمجھ سکتا ہے جسے اللہ تعالٰی ایسا صحیح وجدان، ذوق سلیم اور ملکہ راسخ عطا فرما دے جو اللہ تعالٰی نے حضرت یوسف (عليه السلام) کو عطا فرمایا۔",
