      "number": 50,
      "arFull": "وَقَالَ الْمَلِكُ ائْتُوْنِیْ بِهٖ ۚ فَلَمَّا جَآءَهُ الرَّسُوْلُ قَالَ ارْجِعْ اِلٰی رَبِّكَ فَسْـَٔلْهُ مَا بَالُ النِّسْوَةِ الّٰتِیْ قَطَّعْنَ اَیْدِیَهُنَّ ؕ اِنَّ رَبِّیْ بِكَیْدِهِنَّ عَلِیْمٌ ۟",
      "ur": "اور بادشاه نے کہا یوسف کو میرے پاس لاؤ[1] ، جب قاصد یوسف کے پاس پہنچا تو انہوں نے کہا، اپنے بادشاه کے پاس واپس جا اور اس سے پوچھ کہ ان عورتوں کا حقیقی واقعہ کیا ہے جنہوں نے اپنے ہاتھ کاٹ لئے[2]، تھے؟ ان کے حیلے کو (صحیح طور پر) جاننے واﻻ میرا پروردگار ہی ہے.",
      "en": "And the king said, \"Bring him to me.\" But when the messenger came to him, [Joseph] said, \"Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan.\"",
      "footnotesUr": "[1] مطلب یہ ہے کہ جب وہ شخص تعبیر دریافت کر کے بادشاہ کے پاس گیا اور اسے تعبیر بتائی تو وہ اس تعبیر سے اور حضرت یوسف (عليه السلام) کی بتلائی ہوئی تدبیر سے بڑا متاثر ہوا اور اس نے اندازہ لگا لیا کہ یہ شخص، جسے ایک عرصے سے حوالہ زنداں کیا ہوا ہے، غیر معمولی علم و فضل اور اعلٰی صلاحیتوں کا حامل ہے۔ چنانچہ بادشاہ نے انہیں دربار میں پیش کرنے کا حکم دیا۔\n[2] حضرت یوسف (عليه السلام) نے جب دیکھا کہ بادشاہ اب مائل بہ کرم ہے، تو انہوں نے اس طرح محض عنایت خسوانہ سے جیل سے نکلنے کو پسند نہیں فرمایا، بلکہ اپنے کردار کی رفعت اور پاک دامنی کے اثبات کو ترجیح دی تاکہ دنیا کے سامنے آپ کا کردار اور اس کی بلندی واضح ہو جائے۔ کیونکہ داعی الی اللہ کے لئے یہ عفت و پاک بازی اور رفعت کردار بہت ضروری ہے۔",
