      "number": 51,
      "arFull": "قَالَ مَا خَطْبُكُنَّ اِذْ رَاوَدْتُّنَّ یُوْسُفَ عَنْ نَّفْسِهٖ ؕ قُلْنَ حَاشَ لِلّٰهِ مَا عَلِمْنَا عَلَیْهِ مِنْ سُوْٓءٍ ؕ قَالَتِ امْرَاَتُ الْعَزِیْزِ الْـٰٔنَ حَصْحَصَ الْحَقُّ ؗ اَنَا رَاوَدْتُّهٗ عَنْ نَّفْسِهٖ وَاِنَّهٗ لَمِنَ الصّٰدِقِیْنَ ۟",
      "ur": "بادشاه نے پوچھا اے عورتو! اس وقت کا صحیح واقعہ کیا ہے جب تم داؤ فریب کر کے یوسف کو اس کی دلی منشا سے بہکانا چاہتی تھیں، انہوں نے صاف جواب دیا کہ معاذ اللہ ہم نے یوسف میں کوئی برائی نہیں[1] پائی، پھر تو عزیز کی بیوی بھی بول اٹھی کہ اب تو سچی بات نتھر آئی۔ میں نے ہی اسے ورغلایا تھا، اس کے جی سے، اور یقیناً وه سچوں میں سے ہے.[2]",
      "en": "Said [the king to the women], \"What was your condition when you sought to seduce Joseph?\" They said, \"Perfect is Allāh![600] We know about him no evil.\" The wife of al-ʿAzeez said, \"Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.",
      "footnotesUr": "[1] بادشاہ کے استفسار پر تمام عورتوں نے یوسف (عليه السلام) کی پاک دامنی کا اعتراف کیا۔\n[2] اب امرأة العزیز (زلیخا) کے لئے بھی یہ اعتراف کئے بغیر چارہ نہیں رہا کہ یوسف (عليه السلام) بےقصور ہے اور یہ پیش دستی میری ہی طرف سے ہوئی تھی، اس فرشتہ صفت انسان کا اس لغزش سے کوئی تعلق نہیں۔",
      "footnotesEn": "[600] In His ability to create such purity of character.",
