      "number": 53,
      "arFull": "وَمَاۤ اُبَرِّئُ نَفْسِیْ ۚ اِنَّ النَّفْسَ لَاَمَّارَةٌ بِالسُّوْٓءِ اِلَّا مَا رَحِمَ رَبِّیْ ؕ اِنَّ رَبِّیْ غَفُوْرٌ رَّحِیْمٌ ۟",
      "ur": "میں اپنے نفس کی پاکیزگی بیان نہیں کرتا[1] ۔ بیشک نفس تو برائی پر ابھارنے واﻻ ہی ہے[2]، مگر یہ کہ میرا پروردگار ہی اپنا رحم کرے[3]، یقیناً میرا پالنے واﻻ بڑی بخشش کرنے واﻻ اور بہت مہربانی فرمانے واﻻ ہے.",
      "en": "And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful.\"[601]",
      "footnotesUr": "[1] اسے اگر حضرت یوسف (عليه السلام) کا تسلیم کیا جائے تو بطور کسر نفسی کے ہے، ورنہ صاف ظاہر ہے کہ ان کی پاک دامنی ہر طرح سے ثابت ہو چکی تھی۔ اور اگر یہ عزیز مصر کا قول ہے (جیسا کہ امام ابن کثیر کا خیال ہے) تو یہ حقیقت پر مبنی ہے کیونکہ اپنے گناہ کا اور یوسف (عليه السلام) کو بہلانے اور پھسلانے کا اعتراف کر لیا۔\n[2] یہ اس نے اپنی غلطی کی یا اس کی علت بیان کی کہ انسان کا نفس ہی ایسا ہے کہ برائی پر ابھارتا ہے اور اس پر آمادہ کرتا ہے۔\n[3] یعنی نفس کی شرارتوں سے وہی بچتا ہے جس پر اللہ تعالٰی کی رحمت ہو، جیسا کہ حضرت یوسف (عليه السلام) کو اللہ تعالٰی نے بچا لیا۔",
      "footnotesEn": "[601] Although Ibn Katheer attributes the words of verses 52-53 to the wife of al-ʿAzeez, others have concluded that they were spoken by Joseph, thereby justifying his request for an inquiry and acknowledging Allāh's mercy to him.",
