      "arFull": "قَالُوْا تَاللّٰهِ لَقَدْ عَلِمْتُمْ مَّا جِئْنَا لِنُفْسِدَ فِی الْاَرْضِ وَمَا كُنَّا سٰرِقِیْنَ ۟",
