      "ur": "جواب دیا کہ اس کی سزا یہی ہے کہ جس کے اسباب میں سے پایا جائے وہی اس کا بدلہ ہے[1] ۔ ہم تو ایسے ﻇالموں کو یہی سزا دیا کرتے ہیں.[2]",
      "en": "[The brothers] said, \"Its recompense is that he in whose bag it is found - he [himself] will be its recompense.[608] Thus do we recompense the wrongdoers.\"",
      "footnotesUr": "[1] یعنی چور کو کچھ عرصے کے لئے اس شخص کے سپرد کر دیا جاتا ہے جس کی اس نے چوری کی ہوتی تھی۔ یہ حضرت یعقوب (عليه السلام) کی شریعت میں سزا تھی، جس کے مطابق یوسف (عليه السلام) کے بھائیوں نے یہ سزا تجویز کی۔\n[2] یہ قول بھی برادران یوسف (عليه السلام) ہی کا ہے، بعض کے نزدیک یہ یوسف (عليه السلام) کے مصاحبین کا قول ہے کہ انہوں نے کہا کہ ہم بھی ظالموں کو ایسی ہی سزا دیتے ہیں۔ لیکن آیت کا اگلا ٹکڑا کہ ”بادشاہ کے دین میں وہ اپنے بھائی کو پکڑ نہ سکتے تھے“ اس قول کی نفی کرتا ہے۔",
