      "arFull": "قَالُوْۤا ءَاِنَّكَ لَاَنْتَ یُوْسُفُ ؕ قَالَ اَنَا یُوْسُفُ وَهٰذَاۤ اَخِیْ ؗ قَدْ مَنَّ اللّٰهُ عَلَیْنَا ؕ اِنَّهٗ مَنْ یَّتَّقِ وَیَصْبِرْ فَاِنَّ اللّٰهَ لَا یُضِیْعُ اَجْرَ الْمُحْسِنِیْنَ ۟",
      "ur": "انہوں نے کہا کیا (واقعی) تو ہی یوسف (علیہ السلام) ہے[1] ۔ جواب دیا کہ ہاں میں یوسف (علیہ السلام) ہوں اور یہ میرا بھائی ہے۔ اللہ نے ہم پر فضل وکرم کیا، بات یہ ہے کہ جو بھی پرہیز گاری اور صبر کرے تو اللہ تعالیٰ کسی نیکوکار کا اجر ضائع نہیں کرتا.[2]",
      "en": "They said, \"Are you indeed Joseph?\" He said, \"I am Joseph, and this is my brother. Allāh has certainly favored us. Indeed, he who fears Allāh and is patient, then indeed, Allāh does not allow to be lost the reward of those who do good.\"",
      "footnotesUr": "[1] بھائیوں نے جب عزیز مصر کی زبان سے اس یوسف (عليه السلام) کا تذکرہ سنا، جسے انہوں نے بچپن میں کنعان کے ایک تاریک کنویں میں پھینک دیا تھا، تو وہ حیران بھی ہوئے اور غور سے دیکھنے پر مجبور بھی کہ کہیں ہم سے ہم کلام بادشاہ، یوسف (عليه السلام) ہی تو نہیں؟ ورنہ یوسف (عليه السلام) کے قصے کا اسے کس طرح علم ہو سکتا ہے؟ چنانچہ انہوں نے سوال کیا کہ کیا تو یوسف (عليه السلام) ہی تو نہیں؟۔\n[2] سوال کے جواب میں اقرار و اعتراف کے ساتھ، اللہ کا احسان کا ذکر اور صبر و تقویٰ کے نتائج حسنہ بھی بیان کر کے بتلا دیا کہ تم نے مجھے ہلاک کرنے میں کوئی دقیقہ فروگزاشت نہیں کیا۔ لیکن یہ اللہ تعالٰی کا فضل و احسان ہے کہ اس نے نہ صرف یہ کہ کنوئیں سے نجات عطا فرمائی، بلکہ مصر کی فرمانروائی بھی عطا فرما دی اور یہ نتیجہ ہے اس صبر اور تقویٰ کا جس کی توفیق اللہ تعالٰی نے مجھے دی۔",
