      "arFull": "اِذْهَبُوْا بِقَمِیْصِیْ هٰذَا فَاَلْقُوْهُ عَلٰی وَجْهِ اَبِیْ یَاْتِ بَصِیْرًا ۚ وَاْتُوْنِیْ بِاَهْلِكُمْ اَجْمَعِیْنَ ۟۠",
      "ur": "میرا یہ کرتا تم لے جاؤ اور اسے میرے والد کے منھ پر ڈال دو کہ وه دیکھنے لگیں[1] ، اور آجائیں اور اپنے تمام خاندان کو میرے پاس لےآؤ.[2]",
