      "arFull": "وَلَمَّا فَصَلَتِ الْعِیْرُ قَالَ اَبُوْهُمْ اِنِّیْ لَاَجِدُ رِیْحَ یُوْسُفَ لَوْلَاۤ اَنْ تُفَنِّدُوْنِ ۟",
