      "number": 111,
      "arFull": "لَقَدْ كَانَ فِیْ قَصَصِهِمْ عِبْرَةٌ لِّاُولِی الْاَلْبَابِ ؕ مَا كَانَ حَدِیْثًا یُّفْتَرٰی وَلٰكِنْ تَصْدِیْقَ الَّذِیْ بَیْنَ یَدَیْهِ وَتَفْصِیْلَ كُلِّ شَیْءٍ وَّهُدًی وَّرَحْمَةً لِّقَوْمٍ یُّؤْمِنُوْنَ ۟۠",
      "ur": "ان کے بیان میں عقل والوں کے لئے یقیناً نصیحت اور عبرت ہے، یہ قرآن جھوٹ بنائی ہوئی بات نہیں بلکہ یہ تصدیق ہے ان کتابوں کی جو اس سے پہلے کی ہیں، کھول کھول کر بیان کرنے واﻻ ہے ہر چیز کو اور ہدایت اور رحمت ہے ایمان دار لوگوں کے لئے.[1]",
      "en": "There was certainly in their stories a lesson for those of understanding. Never was it [i.e., the Qur’ān] a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.",
      "footnotesUr": "[1] یعنی قرآن، جس میں قصہ یوسف (عليه السلام) اور دیگر قوموں کے واقعات بیان کئے گئے ہیں کوئی گھڑا ہوا نہیں ہے۔ بلکہ یہ پچھلی کتابوں کی تصدیق کرنے والا ہے اور اس میں دین کے بارے میں ساری ضروری باتوں کی تفصیل ہے اور ایمان داروں کے لئے ہدایت و رحمت۔",
